blog/dev/Daily_Read/math-random-is-not-r.content:
랜덤이란 무엇인가?
우리는 흔히 “랜덤”이라는 단어를 사용합니다. 하지만 컴퓨터에서의 “랜덤”은 우리가 생각하는 진정한 무작위와는 다릅니다.
진정한 랜덤 (True Random)

예측 불가능
패턴이 없음
재현 불가능
예: 방사성 붕괴, 양자 현상, 주사위 굴리기

의사 랜덤 (Pseudo Random)

알고리즘으로 생성
결정론적 (같은 시드 = 같은 결과)
패턴이 존재 (주기가 있음)
예: 컴퓨터의 Math.random()

Math.random()의 정체
기본 사용법
// 0 이상 1 미만의 부동소수점 난수 반환
Math.random();  // 0.347281947...

// 정수 뽑기
Math.floor(Math.random() * 10);  // 0~9 사이의 정수
Math.floor(Math.random() * 100);  // 0~99 사이의 정수

// 범위 지정
function randomRange(min, max) {
  return Math.floor(Math.random() * (max - min + 1)) + min;
}

randomRange(1, 6);  // 1~6 사이 (주사위)
실제 동작 방식
Math.random()은 **PRNG(Pseudorandom Number Generator, 의사 난수 생성기)**를 사용합니다.
// 실제로는 이런 알고리즘을 사용 (단순화된 예시)
class SimplePRNG {
  constructor(seed) {
    this.seed = seed;
  }

  next() {
    // Linear Congruential Generator (LCG) 알고리즘
    this.seed = (this.seed * 1103515245 + 12345) % 2147483648;
    return this.seed / 2147483648;
  }
}

const rng = new SimplePRNG(Date.now());
console.log(rng.next());  // 0.347281947...
console.log(rng.next());  // 0.892743561...
Math.random()은 무작위가 아니다?
증명 1: 시드 재현성
같은 시드값으로 시작하면 같은 수열이 생성됩니다.
// V8 엔진의 내부 구현 (개념적 예시)
let seed = 12345;

function predictableRandom() {
  seed = (seed * 1103515245 + 12345) &amp; 0x7fffffff;
  return seed / 2147483648;
}

// 항상 같은 순서
console.log(predictableRandom());  // 0.347281947...
console.log(predictableRandom());  // 0.892743561...

// 시드를 초기화하면 같은 수열 반복
seed = 12345;
console.log(predictableRandom());  // 0.347281947... (동일!)
증명 2: 주기성
PRNG는 유한한 주기를 가집니다. 충분히 많은 난수를 생성하면 패턴이 반복됩니다.
// 간단한 LCG의 주기 문제
class BadRNG {
  constructor(seed) {
    this.seed = seed;
    this.history = new Set();
  }

  next() {
    this.seed = (this.seed * 1103515245 + 12345) % 65536;

    if (this.history.has(this.seed)) {
      console.log(&#039;주기 감지! 같은 값이 반복됩니다.&#039;);
    }
    this.history.add(this.seed);

    return this.seed / 65536;
  }
}
증명 3: 통계적 편향
완벽한 PRNG는 통계적으로 균등 분포를 가져야 하지만, 많은 구현들이 미묘한 편향을 가집니다.
// 편향 테스트
function testBias(samples = 1000000) {
  const buckets = Array(10).fill(0);

  for (let i = 0; i &lt; samples; i++) {
    const num = Math.floor(Math.random() * 10);
    buckets[num]++;
  }

  console.log(&#039;분포:&#039;, buckets);
  console.log(&#039;각 버킷 예상:&#039;, samples / 10);

  // 이론적으로는 각 버킷이 100,000개씩
  // 실제로는 약간의 편차 존재
}

testBias();
JavaScript에서 정수 뽑기의 함정
흔한 실수
// ❌ 나쁜 방법: 편향 발생
Math.round(Math.random() * 10);  // 0과 10이 다른 숫자의 절반 확률

// ✅ 올바른 방법
Math.floor(Math.random() * 11);  // 0~10 균등 분포
편향 원인
// round를 사용하면
// 0: [0, 0.5)    -&gt; 50% 확률
// 1: [0.5, 1.5)  -&gt; 100% 확률
// ...
// 10: [9.5, 10)  -&gt; 50% 확률

// floor를 사용하면
// 0: [0, 1)      -&gt; 100% 확률
// 1: [1, 2)      -&gt; 100% 확률
// ...
// 10: [10, 11)   -&gt; 100% 확률
더 나은 난수 생성 방법
1. Web Crypto API (권장)
진정한 난수에 가까운 암호학적으로 안전한 난수를 생성합니다.
// crypto.getRandomValues()
const array = new Uint32Array(1);
crypto.getRandomValues(array);
const randomNumber = array[0] / (0xFFFFFFFF + 1);

console.log(randomNumber);  // 진짜 랜덤에 가까움

// 헬퍼 함수
function cryptoRandom() {
  const array = new Uint32Array(1);
  crypto.getRandomValues(array);
  return array[0] / (0xFFFFFFFF + 1);
}

function cryptoRandomInt(min, max) {
  const range = max - min + 1;
  const bytesNeeded = Math.ceil(Math.log2(range) / 8);
  const maxValue = Math.pow(256, bytesNeeded);
  const randomBytes = new Uint8Array(bytesNeeded);

  let randomValue;
  do {
    crypto.getRandomValues(randomBytes);
    randomValue = 0;
    for (let i = 0; i &lt; bytesNeeded; i++) {
      randomValue = (randomValue &lt;&lt; 8) + randomBytes[i];
    }
  } while (randomValue &gt;= maxValue - (maxValue % range));

  return min + (randomValue % range);
}

console.log(cryptoRandomInt(1, 6));  // 진짜 랜덤 주사위
2. Node.js crypto 모듈
const crypto = require(&#039;crypto&#039;);

// 진정한 난수
function secureRandom() {
  return crypto.randomInt(0, Number.MAX_SAFE_INTEGER) / Number.MAX_SAFE_INTEGER;
}

// 범위 지정
function secureRandomInt(min, max) {
  return crypto.randomInt(min, max + 1);
}

console.log(secureRandomInt(1, 6));
3. 외부 엔트로피 사용
// 사용자 입력, 시스템 이벤트 등을 조합
class EntropyPool {
  constructor() {
    this.pool = [];
  }

  addEntropy(value) {
    this.pool.push(value);
  }

  generate() {
    // 여러 소스의 엔트로피 혼합
    const mouseMovement = Math.random();
    const timestamp = Date.now();
    const performance = performance.now();

    const combined = mouseMovement + timestamp + performance;
    return (combined % 1);
  }
}
언제 어떤 것을 사용할까?
Math.random()을 사용해도 되는 경우
✅ 게임의 시각적 효과
✅ UI 애니메이션의 랜덤 딜레이
✅ 낮은 보안 요구사항의 일반 애플리케이션
// 괜찮은 사용 예
function randomParticlePosition() {
  return {
    x: Math.random() * canvas.width,
    y: Math.random() * canvas.height
  };
}
crypto를 사용해야 하는 경우
🔒 보안 토큰 생성
🔒 비밀번호 생성
🔒 암호화 키
🔒 세션 ID
🔒 무결성이 중요한 랜덤 선택
// 반드시 crypto 사용
function generateSecureToken(length = 32) {
  const array = new Uint8Array(length);
  crypto.getRandomValues(array);
  return Array.from(array, byte =&gt; byte.toString(16).padStart(2, &#039;0&#039;)).join(&#039;&#039;);
}

const token = generateSecureToken();
console.log(token);  // &quot;a3f5c7e9d2b4f8a1c5e7d9f3b2a4c6e8...&quot;
결론
핵심 정리

Math.random()은 의사 난수: 진정한 무작위가 아니라 알고리즘으로 생성
결정론적: 같은 시드면 같은 수열
주기성 존재: 충분히 많이 생성하면 패턴 반복
용도에 따른 선택:

일반적인 용도 → Math.random()
보안이 중요한 경우 → crypto.getRandomValues()



실전 가이드
// 일반 용도
const x = Math.random();
const dice = Math.floor(Math.random() * 6) + 1;

// 보안 용도
const token = crypto.getRandomValues(new Uint8Array(32));
const secureId = [...token].map(b =&gt; b.toString(16).padStart(2, &#039;0&#039;)).join(&#039;&#039;);
진정한 무작위를 만들어 보자는 컴퓨터 과학의 오랜 과제입니다. 완벽한 해답은 아직 없지만, 우리는 용도에 맞는 최선의 방법을 선택할 수 있습니다.

참고 자료

How does JavaScript’s Math.random() generate random numbers?
MDN: Math.random()
MDN: Crypto.getRandomValues()
PRNG 알고리즘: Linear Congruential Generator (LCG)

blog/dev/Daily_Read/setState를-비동기-함수라-오해.content:
TL;DR

setState는 비동기 함수가 아니다. 다만 React가 성능 최적화를 위해 상태 업데이트를 배치(batch)로 처리할 뿐이다.

흔한 오해
많은 개발자들이 setState를 “비동기 함수”라고 말합니다.
class Counter extends React.Component {
  state = { count: 0 };

  handleClick = () =&gt; {
    this.setState({ count: this.state.count + 1 });
    console.log(this.state.count);  // 왜 0일까? &quot;비동기&quot;라서?
  };
}
위 코드에서 console.log가 업데이트된 값을 출력하지 않기 때문에, “setState가 비동기 함수”라고 생각하게 됩니다.
하지만 이것은 정확한 표현이 아닙니다.
setState는 비동기 함수가 아니다
비동기 함수의 정의
진짜 비동기 함수는 이렇습니다:
// Promise를 반환하는 비동기 함수
async function fetchData() {
  const response = await fetch(&#039;/api/data&#039;);
  return response.json();
}

// setTimeout/setInterval 등의 비동기 작업
setTimeout(() =&gt; {
  console.log(&#039;비동기 실행&#039;);
}, 1000);
setState의 실제 특성
// setState는 Promise를 반환하지 않는다
this.setState({ count: 1 });  // Promise가 아님!

// await을 사용할 수 없다
await this.setState({ count: 1 });  // ❌ 에러는 아니지만 의미 없음

// 콜백은 있지만 이것도 비동기의 증거는 아님
this.setState({ count: 1 }, () =&gt; {
  console.log(&#039;업데이트 완료&#039;);
});
진짜 이유: 배치 업데이트 (Batching)
React의 성능 최적화 전략
React는 성능을 위해 여러 setState 호출을 모아서 한 번에 처리합니다.
handleClick = () =&gt; {
  // React 이벤트 핸들러 내부
  this.setState({ count: this.state.count + 1 });
  this.setState({ count: this.state.count + 1 });
  this.setState({ count: this.state.count + 1 });

  // 3번 호출했지만, 리렌더링은 1번만 발생!
  // count는 1 증가 (3이 아님)
};
왜 배치 업데이트를 할까?
성능 때문입니다.
// 배치 없이 즉시 적용한다면?
this.setState({ a: 1 });  // 리렌더링
this.setState({ b: 2 });  // 리렌더링
this.setState({ c: 3 });  // 리렌더링
// → 3번의 불필요한 리렌더링!

// 배치 업데이트
this.setState({ a: 1 });
this.setState({ b: 2 });
this.setState({ c: 3 });
// → 모두 모아서 1번만 리렌더링!
언제 배치 업데이트가 일어날까?
React가 제어하는 컨텍스트 (Batching O)
// 1. 이벤트 핸들러
handleClick = () =&gt; {
  this.setState({ count: 1 });  // 배치됨
  this.setState({ count: 2 });  // 배치됨
};

// 2. 라이프사이클 메서드
componentDidMount() {
  this.setState({ count: 1 });  // 배치됨
  this.setState({ count: 2 });  // 배치됨
}

// 3. useEffect (Hooks)
useEffect(() =&gt; {
  setCount(1);  // 배치됨
  setCount(2);  // 배치됨
}, []);
React가 제어하지 못하는 컨텍스트 (Batching X) - React 17 이하
// 1. setTimeout
handleClick = () =&gt; {
  setTimeout(() =&gt; {
    this.setState({ count: 1 });  // 즉시 적용!
    console.log(this.state.count);  // 1 출력
    this.setState({ count: 2 });  // 즉시 적용!
    console.log(this.state.count);  // 2 출력
  }, 0);
};

// 2. Promise
handleClick = () =&gt; {
  fetch(&#039;/api&#039;).then(() =&gt; {
    this.setState({ count: 1 });  // 즉시 적용!
    this.setState({ count: 2 });  // 즉시 적용!
  });
};

// 3. 네이티브 이벤트 리스너
componentDidMount() {
  document.addEventListener(&#039;click&#039;, () =&gt; {
    this.setState({ count: 1 });  // 즉시 적용!
    this.setState({ count: 2 });  // 즉시 적용!
  });
}
React 18의 변화: Automatic Batching
React 18부터는 모든 곳에서 배치!
// React 18+
handleClick = () =&gt; {
  setTimeout(() =&gt; {
    setCount(c =&gt; c + 1);  // 배치됨!
    setCount(c =&gt; c + 1);  // 배치됨!
    // 두 업데이트가 함께 처리됨
  }, 1000);
};

fetch(&#039;/api&#039;).then(() =&gt; {
  setCount(c =&gt; c + 1);  // 배치됨!
  setFlag(f =&gt; !f);      // 배치됨!
  // 함께 처리됨
});
배치를 원하지 않는다면?
import { flushSync } from &#039;react-dom&#039;;

function handleClick() {
  flushSync(() =&gt; {
    setCount(c =&gt; c + 1);
  });
  // 여기서 DOM이 이미 업데이트됨

  flushSync(() =&gt; {
    setFlag(f =&gt; !f);
  });
  // 별도로 즉시 업데이트됨
}
올바른 setState 사용법
1. 함수형 업데이트 사용
// ❌ 잘못된 방법 - 이전 state 직접 참조
this.setState({ count: this.state.count + 1 });
this.setState({ count: this.state.count + 1 });
this.setState({ count: this.state.count + 1 });
// count: 1 (의도와 다름)

// ✅ 올바른 방법 - 함수형 업데이트
this.setState(prevState =&gt; ({ count: prevState.count + 1 }));
this.setState(prevState =&gt; ({ count: prevState.count + 1 }));
this.setState(prevState =&gt; ({ count: prevState.count + 1 }));
// count: 3 (의도대로)
2. 콜백으로 업데이트 후 작업
// 업데이트 완료 후 작업이 필요하다면
this.setState(
  { count: this.state.count + 1 },
  () =&gt; {
    console.log(&#039;업데이트 완료:&#039;, this.state.count);
    // 여기서는 업데이트된 값을 사용 가능
  }
);
3. Hooks에서의 패턴
function Counter() {
  const [count, setCount] = useState(0);

  const handleClick = () =&gt; {
    // ✅ 함수형 업데이트
    setCount(c =&gt; c + 1);
    setCount(c =&gt; c + 1);
    setCount(c =&gt; c + 1);
    // count: 3
  };

  // 업데이트 후 작업은 useEffect로
  useEffect(() =&gt; {
    console.log(&#039;count 변경됨:&#039;, count);
  }, [count]);
}
실전 예제
예제 1: 카운터
function Counter() {
  const [count, setCount] = useState(0);

  const increment = () =&gt; {
    // ❌ 잘못된 방법
    setCount(count + 1);
    setCount(count + 1);
    setCount(count + 1);
    // count: 1만 증가

    // ✅ 올바른 방법
    setCount(c =&gt; c + 1);
    setCount(c =&gt; c + 1);
    setCount(c =&gt; c + 1);
    // count: 3 증가
  };

  return (
    &lt;div&gt;
      &lt;p&gt;Count: {count}&lt;/p&gt;
      &lt;button onClick={increment}&gt;+3&lt;/button&gt;
    &lt;/div&gt;
  );
}
예제 2: 폼 입력
function Form() {
  const [formData, setFormData] = useState({ name: &#039;&#039;, email: &#039;&#039; });

  const handleChange = (e) =&gt; {
    const { name, value } = e.target;

    // ✅ 함수형 업데이트로 안전하게
    setFormData(prev =&gt; ({
      ...prev,
      [name]: value
    }));
  };

  return (
    &lt;form&gt;
      &lt;input name=&quot;name&quot; onChange={handleChange} /&gt;
      &lt;input name=&quot;email&quot; onChange={handleChange} /&gt;
    &lt;/form&gt;
  );
}
예제 3: API 호출 후 상태 업데이트
function UserProfile() {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(false);

  const fetchUser = async () =&gt; {
    setLoading(true);

    try {
      const response = await fetch(&#039;/api/user&#039;);
      const data = await response.json();

      // React 18+: 자동으로 배치됨
      setUser(data);
      setLoading(false);
    } catch (error) {
      setLoading(false);
    }
  };

  return &lt;div&gt;{loading ? &#039;Loading...&#039; : user?.name}&lt;/div&gt;;
}
정리
setState는 비동기 함수가 아니다
❌ 잘못된 이해: “setState는 비동기 함수다”
✅ 올바른 이해: “React가 성능 최적화를 위해 배치 처리한다”
핵심 포인트

배치 업데이트: 여러 setState를 모아서 한 번에 처리
React 17 이하: React 이벤트 핸들러 내에서만 배치
React 18+: 모든 곳에서 자동 배치 (Automatic Batching)
함수형 업데이트: 이전 state 기반 업데이트 시 필수
콜백 사용: 업데이트 완료 후 작업이 필요할 때

실천 가이드
// ✅ 항상 함수형 업데이트 사용
setState(prev =&gt; ({ ...prev, newValue }));

// ✅ 업데이트 후 작업은 useEffect
useEffect(() =&gt; {
  // state가 변경된 후 실행
}, [state]);

// ✅ 즉시 DOM 업데이트가 필요하면 flushSync (React 18+)
import { flushSync } from &#039;react-dom&#039;;
flushSync(() =&gt; {
  setState(newValue);
});

참고 자료

setState is not async
React 공식 문서: State and Lifecycle
React 18: Automatic Batching

blog/dev/Daily_Read/typescript-dts-decla.content:
TL;DR

.d.ts 파일은 코드의 타입 추론을 돕는 타입 선언 파일(Type Declaration File)입니다.
해당 파일을 통해 기존 JavaScript 모듈의 모양을 설명하고, TypeScript에서 타입을 검사할 수 있게 합니다.

들어가며
TypeScript 프로젝트를 작업하다 보면 .d.ts 확장자를 가진 파일들을 자주 보게 됩니다.
node_modules/
  @types/
    react/
      index.d.ts
      global.d.ts
    node/
      index.d.ts
  lodash/
    lodash.d.ts

이 파일들은 무엇이고, 왜 필요할까요?
.d.ts 파일이란?
Declaration File (선언 파일)
.d.ts 파일은 Declaration File의 약자로, TypeScript의 타입 정보만을 담고 있는 파일입니다.
// math.d.ts - 선언 파일
export function add(a: number, b: number): number;
export function subtract(a: number, b: number): number;

// 실제 구현 코드는 없고, 타입 정보만 있음
실제 구현과의 관계
// math.js - 실제 JavaScript 구현
export function add(a, b) {
  return a + b;
}

export function subtract(a, b) {
  return a - b;
}
// math.d.ts - 타입 선언
export function add(a: number, b: number): number;
export function subtract(a: number, b: number): number;
TypeScript 컴파일러는 .js 파일의 구현과 .d.ts 파일의 선언을 매칭하여 타입 체크를 수행합니다.
왜 필요한가?
1. JavaScript 라이브러리에 타입 추가
JavaScript로 작성된 라이브러리를 TypeScript에서 사용할 때 필요합니다.
// lodash는 JavaScript로 작성됨
import _ from &#039;lodash&#039;;

// TypeScript에서 타입 체크를 받으려면?
_.chunk([&#039;a&#039;, &#039;b&#039;, &#039;c&#039;, &#039;d&#039;], 2);
//  ^ 어떤 파라미터를 받는지 알 수 있을까?
해결책: @types/lodash 패키지
// @types/lodash/index.d.ts
declare module &#039;lodash&#039; {
  export function chunk&lt;T&gt;(array: T[], size: number): T[][];
  // ... 수백 개의 함수 선언
}
이제 TypeScript가 타입을 알 수 있습니다!
2. 타입 체크와 자동완성
import _ from &#039;lodash&#039;;

// 자동완성 제공
_.ch  // chunk, chain 등이 자동완성됨

// 타입 체크
_.chunk([&#039;a&#039;, &#039;b&#039;, &#039;c&#039;], &#039;2&#039;);
//                       ^^^ ❌ Error: Argument of type &#039;string&#039; is not assignable to parameter of type &#039;number&#039;
3. API 문서 역할
// user.d.ts
interface User {
  /** 사용자 고유 ID */
  id: number;

  /** 사용자 이름 (2-50자) */
  name: string;

  /** 이메일 주소 */
  email: string;
}

/**
 * 사용자 정보를 가져옵니다
 * @param id 사용자 ID
 * @returns 사용자 객체 또는 null
 */
export function getUser(id: number): Promise&lt;User | null&gt;;
선언 파일의 위치
1. DefinitelyTyped (@types)
대부분의 유명 JavaScript 라이브러리는 @types 패키지로 타입 정의가 제공됩니다.
# React 타입 설치
npm install --save-dev @types/react

# Node.js 타입 설치
npm install --save-dev @types/node

# Express 타입 설치
npm install --save-dev @types/express
2. 라이브러리 자체에 포함
일부 라이브러리는 자체적으로 .d.ts 파일을 포함합니다.
// package.json
{
  &quot;name&quot;: &quot;my-library&quot;,
  &quot;version&quot;: &quot;1.0.0&quot;,
  &quot;main&quot;: &quot;dist/index.js&quot;,
  &quot;types&quot;: &quot;dist/index.d.ts&quot;  // 타입 선언 파일 위치
}
3. 프로젝트 내부 선언
src/
  types/
    global.d.ts
    api.d.ts
    models.d.ts

Type Definition이 없는 모듈 다루기
문제 상황
// untyped-library는 타입 정의가 없는 라이브러리
import something from &#039;untyped-library&#039;;
//                    ^^^^^^^^^^^^^^^^^^
// ❌ Could not find a declaration file for module &#039;untyped-library&#039;
해결 방법 1: 모듈 선언으로 침묵시키기
// src/types/untyped-modules.d.ts
declare module &#039;untyped-library&#039;;
이제 에러는 사라지지만, 타입은 any가 됩니다.
import something from &#039;untyped-library&#039;;
// something의 타입은 any
해결 방법 2: 직접 타입 정의하기
// src/types/untyped-library.d.ts
declare module &#039;untyped-library&#039; {
  export interface Config {
    apiKey: string;
    timeout?: number;
  }

  export function initialize(config: Config): void;
  export function getData(): Promise&lt;any&gt;;

  const library: {
    version: string;
    initialize: typeof initialize;
    getData: typeof getData;
  };

  export default library;
}
이제 완전한 타입 체크가 가능합니다!
import library, { initialize, getData } from &#039;untyped-library&#039;;

initialize({ apiKey: &#039;abc123&#039; });  // ✅
initialize({ apiKey: 123 });       // ❌ Error: Type &#039;number&#039; is not assignable to type &#039;string&#039;
선언 파일 작성 패턴
함수 선언
// 기본 함수
declare function greet(name: string): string;

// 오버로딩
declare function format(value: string): string;
declare function format(value: number): string;
declare function format(value: Date): string;

// 제네릭
declare function identity&lt;T&gt;(value: T): T;
클래스 선언
declare class EventEmitter {
  constructor();

  on(event: string, listener: Function): this;
  off(event: string, listener: Function): this;
  emit(event: string, ...args: any[]): boolean;
}
인터페이스와 타입
// 인터페이스
interface User {
  id: number;
  name: string;
  email: string;
}

// 타입 별칭
type ID = string | number;

// 유니온 타입
type Status = &#039;pending&#039; | &#039;success&#039; | &#039;error&#039;;
네임스페이스
declare namespace MyLibrary {
  interface Config {
    debug: boolean;
  }

  function init(config: Config): void;

  namespace Utils {
    function formatDate(date: Date): string;
  }
}

// 사용
MyLibrary.init({ debug: true });
MyLibrary.Utils.formatDate(new Date());
모듈 확장 (Module Augmentation)
기존 모듈에 타입을 추가할 수 있습니다.
// express.d.ts
import &#039;express&#039;;

declare module &#039;express&#039; {
  interface Request {
    user?: {
      id: number;
      name: string;
    };
  }
}

// 이제 req.user를 사용할 수 있음
app.get(&#039;/profile&#039;, (req, res) =&gt; {
  console.log(req.user);  // 타입 체크 O
});
전역 선언
// global.d.ts
declare global {
  interface Window {
    myApp: {
      version: string;
      init(): void;
    };
  }

  const API_URL: string;
}

export {};  // 모듈로 만들기 위한 빈 export

// 사용
window.myApp.init();
console.log(API_URL);
실전 예제
예제 1: 외부 CDN 라이브러리
&lt;!-- index.html --&gt;
&lt;script src=&quot;cdn.example.com/awesome-library.js&quot;&gt;&lt;/script&gt;
// awesome-library.d.ts
declare namespace AwesomeLibrary {
  interface Options {
    theme: &#039;light&#039; | &#039;dark&#039;;
    language: string;
  }

  function init(options: Options): void;
  function destroy(): void;
}

// 사용
AwesomeLibrary.init({ theme: &#039;dark&#039;, language: &#039;ko&#039; });
예제 2: Node.js 환경 변수
// env.d.ts
declare namespace NodeJS {
  interface ProcessEnv {
    NODE_ENV: &#039;development&#039; | &#039;production&#039; | &#039;test&#039;;
    API_URL: string;
    API_KEY: string;
    PORT: string;
  }
}

// 사용
const apiUrl = process.env.API_URL;  // string 타입
const port = parseInt(process.env.PORT);
예제 3: 이미지 import
// images.d.ts
declare module &#039;*.png&#039; {
  const value: string;
  export default value;
}

declare module &#039;*.jpg&#039; {
  const value: string;
  export default value;
}

declare module &#039;*.svg&#039; {
  import React from &#039;react&#039;;
  const SVG: React.FC&lt;React.SVGProps&lt;SVGSVGElement&gt;&gt;;
  export default SVG;
}

// 사용
import logo from &#039;./logo.png&#039;;  // string
import Icon from &#039;./icon.svg&#039;;  // React Component
예제 4: CSS Modules
// css-modules.d.ts
declare module &#039;*.module.css&#039; {
  const classes: { [key: string]: string };
  export default classes;
}

declare module &#039;*.module.scss&#039; {
  const classes: { [key: string]: string };
  export default classes;
}

// 사용
import styles from &#039;./Button.module.css&#039;;

&lt;button className={styles.primary}&gt;Click&lt;/button&gt;
.d.ts 파일 자동 생성
tsconfig.json 설정
{
  &quot;compilerOptions&quot;: {
    &quot;declaration&quot;: true,           // .d.ts 파일 생성
    &quot;declarationMap&quot;: true,        // .d.ts.map 파일 생성 (소스맵)
    &quot;outDir&quot;: &quot;./dist&quot;,
    &quot;rootDir&quot;: &quot;./src&quot;
  }
}
소스 코드
// src/math.ts
export function add(a: number, b: number): number {
  return a + b;
}

export function subtract(a: number, b: number): number {
  return a - b;
}
자동 생성된 선언 파일
// dist/math.d.ts
export declare function add(a: number, b: number): number;
export declare function subtract(a: number, b: number): number;
주의사항
1. 구현 코드 포함 불가
// ❌ 잘못된 예
export function greet(name: string): string {
  return `Hello, ${name}`;  // 구현 코드는 .d.ts에 들어가면 안 됨
}

// ✅ 올바른 예
export declare function greet(name: string): string;
2. 타입만 export
// types.d.ts
export interface User {
  id: number;
  name: string;
}

export type Status = &#039;active&#039; | &#039;inactive&#039;;

// 값은 export 불가
export const MAX_USERS = 100;  // ❌ Error
3. declare 키워드 사용
// 모듈 외부에서 사용 가능하도록
declare const API_URL: string;
declare function fetchData(): Promise&lt;any&gt;;
declare class HttpClient {}
결론
핵심 정리

.d.ts 파일은 타입 정보만 담고 있는 선언 파일
JavaScript 라이브러리에 TypeScript 타입을 추가
@types 패키지로 대부분의 유명 라이브러리 커버
타입이 없는 모듈은 직접 선언 가능
tsconfig.json으로 자동 생성 가능

실천 가이드

npm 패키지 만들 때: declaration: true 설정으로 .d.ts 자동 생성
타입 없는 라이브러리 사용 시: 프로젝트 내 선언 파일 작성
전역 타입 추가 시: global.d.ts 파일 활용
모듈 확장 시: declare module로 기존 타입 확장

TypeScript의 타입 시스템을 최대한 활용하려면 선언 파일을 잘 이해하고 활용하는 것이 중요합니다!

참고 자료

What is a d.ts file in TypeScript?
TypeScript 공식 문서: Declaration Files
DefinitelyTyped - 커뮤니티 타입 정의 저장소

blog/dev/Daily_Read/typescript-omit-vs-e.content:
TL;DR

타입을 정의할 때 객체의 특정 프로퍼티를 빼고 싶을 땐 Omit, 유니온 타입의 특정 값을 빼고 싶을 땐 Exclude

들어가며
TypeScript를 사용하다 보면 기존 타입에서 일부를 제외한 새로운 타입을 만들어야 할 때가 많습니다. 이때 자주 사용하는 두 가지 유틸리티 타입이 바로 Omit과 Exclude입니다.
이 둘은 이름도 비슷하고 역할도 비슷해 보이지만, 사용 대상이 완전히 다릅니다.
Omit: 객체 타입에서 프로퍼티 제외하기
기본 사용법
type User = {
  id: number;
  name: string;
  email: string;
  password: string;
};

// password를 제외한 나머지 프로퍼티만 가진 타입
type PublicUser = Omit&lt;User, &#039;password&#039;&gt;;
// { id: number; name: string; email: string; }
문법
Omit&lt;T, K&gt;

T: 원본 객체 타입
K: 제외할 프로퍼티 키(문자열 리터럴 타입)

여러 프로퍼티 제외하기
type User = {
  id: number;
  name: string;
  email: string;
  password: string;
  createdAt: Date;
  updatedAt: Date;
};

// 여러 프로퍼티를 유니온으로 제외
type UserDTO = Omit&lt;User, &#039;password&#039; | &#039;createdAt&#039; | &#039;updatedAt&#039;&gt;;
// { id: number; name: string; email: string; }
실전 예시
API 응답과 요청 타입 분리:
interface Post {
  id: number;
  title: string;
  content: string;
  authorId: number;
  createdAt: Date;
  updatedAt: Date;
}

// POST 요청시 사용 (id, createdAt, updatedAt는 서버에서 생성)
type CreatePostDTO = Omit&lt;Post, &#039;id&#039; | &#039;createdAt&#039; | &#039;updatedAt&#039;&gt;;
// { title: string; content: string; authorId: number; }

// PUT 요청시 사용 (id는 URL 파라미터로, 날짜는 서버에서 생성)
type UpdatePostDTO = Omit&lt;Post, &#039;id&#039; | &#039;authorId&#039; | &#039;createdAt&#039; | &#039;updatedAt&#039;&gt;;
// { title: string; content: string; }
Exclude: 유니온 타입에서 멤버 제외하기
기본 사용법
type Status = &#039;pending&#039; | &#039;approved&#039; | &#039;rejected&#039; | &#039;cancelled&#039;;

// &#039;cancelled&#039;를 제외한 나머지 상태들
type ActiveStatus = Exclude&lt;Status, &#039;cancelled&#039;&gt;;
// &#039;pending&#039; | &#039;approved&#039; | &#039;rejected&#039;
문법
Exclude&lt;T, U&gt;

T: 원본 유니온 타입
U: 제외할 타입

여러 멤버 제외하기
type HttpMethod = &#039;GET&#039; | &#039;POST&#039; | &#039;PUT&#039; | &#039;DELETE&#039; | &#039;PATCH&#039; | &#039;OPTIONS&#039; | &#039;HEAD&#039;;

// 여러 멤버를 유니온으로 제외
type CommonHttpMethod = Exclude&lt;HttpMethod, &#039;OPTIONS&#039; | &#039;HEAD&#039;&gt;;
// &#039;GET&#039; | &#039;POST&#039; | &#039;PUT&#039; | &#039;DELETE&#039; | &#039;PATCH&#039;
실전 예시
조건부 타입과 함께 사용:
type Primitive = string | number | boolean | null | undefined;

// 객체와 함수만 남기기 (primitive 타입 제외)
type NonPrimitive&lt;T&gt; = Exclude&lt;T, Primitive&gt;;

type Example = NonPrimitive&lt;string | number | object | Function&gt;;
// object | Function
이벤트 핸들러 타입:
type MouseEvent = &#039;click&#039; | &#039;dblclick&#039; | &#039;mousedown&#039; | &#039;mouseup&#039; | &#039;mousemove&#039;;
type KeyboardEvent = &#039;keydown&#039; | &#039;keyup&#039; | &#039;keypress&#039;;

type AllEvents = MouseEvent | KeyboardEvent;

// 마우스 이벤트만 제외
type OnlyKeyboardEvents = Exclude&lt;AllEvents, MouseEvent&gt;;
// &#039;keydown&#039; | &#039;keyup&#039; | &#039;keypress&#039;
핵심 차이점






























특징OmitExclude대상객체 타입유니온 타입제외하는 것객체의 프로퍼티 (키)유니온의 멤버 (타입)결과새로운 객체 타입새로운 유니온 타입사용 상황객체에서 일부 필드 제거유니온에서 일부 옵션 제거
실전 조합 예시
Omit과 Exclude를 함께 사용
interface User {
  id: number;
  name: string;
  role: &#039;admin&#039; | &#039;user&#039; | &#039;guest&#039;;
  email: string;
}

// 1. Omit으로 프로퍼티 제외
type UserWithoutId = Omit&lt;User, &#039;id&#039;&gt;;

// 2. Omit + 타입 재정의로 role 옵션 제한
type LimitedUser = Omit&lt;User, &#039;role&#039;&gt; &amp; {
  role: Exclude&lt;User[&#039;role&#039;], &#039;admin&#039;&gt;;  // &#039;admin&#039;을 제외한 role
};
// { id: number; name: string; email: string; role: &#039;user&#039; | &#039;guest&#039;; }
실무 패턴: API 타입 관리
// 기본 엔티티
interface Product {
  id: string;
  name: string;
  description: string;
  price: number;
  category: &#039;electronics&#039; | &#039;clothing&#039; | &#039;food&#039; | &#039;books&#039;;
  status: &#039;active&#039; | &#039;inactive&#039; | &#039;deleted&#039;;
  createdAt: Date;
  updatedAt: Date;
}

// CREATE: id, 날짜 필드 제외
type CreateProductDTO = Omit&lt;Product, &#039;id&#039; | &#039;createdAt&#039; | &#039;updatedAt&#039;&gt;;

// UPDATE: id, 날짜 필드 제외 + 모든 필드 optional
type UpdateProductDTO = Partial&lt;Omit&lt;Product, &#039;id&#039; | &#039;createdAt&#039; | &#039;updatedAt&#039;&gt;&gt;;

// LIST: deleted 상태 제외
type ListProduct = Omit&lt;Product, &#039;status&#039;&gt; &amp; {
  status: Exclude&lt;Product[&#039;status&#039;], &#039;deleted&#039;&gt;;
};
내부 구현 이해하기
Omit의 내부 구현
type Omit&lt;T, K extends keyof any&gt; = Pick&lt;T, Exclude&lt;keyof T, K&gt;&gt;;
흥미롭게도 Omit은 내부적으로 Exclude를 사용합니다!

keyof T로 모든 키를 유니온 타입으로 만듦
Exclude로 제외할 키를 빼냄
Pick으로 남은 키들만 추출

Exclude의 내부 구현
type Exclude&lt;T, U&gt; = T extends U ? never : T;
조건부 타입을 사용하여 각 멤버를 검사하고, U에 속하면 never, 아니면 그대로 유지합니다.
헷갈리지 않는 팁
1. 명확한 기준

객체의 모양을 다룬다 → Omit
가능한 값들의 집합을 다룬다 → Exclude

2. 시각적 구분
// Omit: 중괄호 { } 안에서
type Result1 = Omit&lt;{ a: number; b: string }, &#039;b&#039;&gt;;

// Exclude: 파이프 | 사이에서
type Result2 = Exclude&lt;&#039;a&#039; | &#039;b&#039; | &#039;c&#039;, &#039;b&#039;&gt;;
3. 에러 메시지로 확인
잘못 사용하면 TypeScript가 알려줍니다:
type Wrong1 = Omit&lt;&#039;a&#039; | &#039;b&#039;, &#039;a&#039;&gt;;
// ❌ Omit은 객체 타입에만 사용

type Wrong2 = Exclude&lt;{ a: number }, &#039;a&#039;&gt;;
// ⚠️ 의도한 대로 작동하지 않음
결론

Omit: 객체 타입에서 프로퍼티 제외
Exclude: 유니온 타입에서 멤버 제외

이 둘의 차이를 명확히 이해하면 TypeScript로 더 정교한 타입 시스템을 구축할 수 있습니다.
체크리스트
제외하고 싶은 대상이:

☐ 객체의 특정 필드인가? → Omit
☐ 유니온의 특정 옵션인가? → Exclude


참고 자료

TypeScript 공식 문서: Utility Types
